changeSet.sql:
alter table modeling_warehouse_plan_policy
    add constraint ck_warehouse_plan_standard_coverage
    check (standard_coverage in ('NONE','KEY_AND_MEASURE','ALL_FIELDS'));
alter table modeling_warehouse_plan_policy
    add constraint ck_warehouse_plan_quality_gate
    check (quality_gate in ('ADVISORY','BLOCKING'));

rollback.sql:
DO $$
BEGIN
    IF EXISTS (
        SELECT 1
          FROM modeling_warehouse_plan_policy
         WHERE standard_coverage <> 'ALL_FIELDS'
            OR quality_gate <> 'BLOCKING'
    ) THEN
        RAISE EXCEPTION 'ROLLBACK_BLOCKED_WAREHOUSE_GOVERNANCE_POLICY_DATA_EXISTS';
    END IF;
END $$;
